// The page has: <h1 id="title">, <button id="btn">, and <p id="output">

const titleEl = document.getElementById('title');
titleEl.textContent = 'Welcome to my Portfolio!';

const btn = document.getElementById('btn');
const output = document.getElementById('output');

// 3. Declare count, then add a click listener that increments
// it and shows 'You clicked X times!' using a template literal

hints:
let count = 0;
btn.addEventListener('click', function() {
  count++;
  output.textContent = `You clicked ${count} times!`;
});
